import type {ToolDefinition} from '../../types/ai.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws synchronously at register time naming the tool when inputSchema is uncompilable', () => {
    const registry = new ToolRegistry();
    const invalidSchema = {type: 'object', properties: {count: {type: 'not-valid'}}};

    expect(() =>
      registry.register({name: 'count_items', description: 'Counts items', inputSchema: invalidSchema}, async () => '0')
    ).toThrow(/count_items/);
  });

  it('reuses the static compiled validator across ten execute calls without re-reading inputSchema', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    let executorCalls = 0;
    const staticSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition: ToolDefinition = {
      name: 'static_weather',
      description: 'Static weather tool',
      get inputSchema() {
        schemaReads += 1;
        return staticSchema;
      },
    };

    registry.register(definition, async () => {
      executorCalls += 1;
      return 'ok';
    });

    for (let index = 0; index < 9; index += 1) {
      await registry.execute('static_weather', {location: 'Paris'});
    }
    await registry.execute('static_weather', {});

    expect({schemaReads, executorCalls}).toEqual({schemaReads: 1, executorCalls: 9});
  });

  it('validates dynamic tool definitions against the current schema and caches compiled validators by reference', async () => {
    const registry = new ToolRegistry();
    let cityPropertiesReads = 0;
    let executorCalls = 0;
    const cityProperties = {city: {type: 'string'}};
    const citySchema: Record<string, unknown> = {
      type: 'object',
      get properties() {
        cityPropertiesReads += 1;
        return cityProperties;
      },
      required: ['city'],
    };
    const zipSchema: Record<string, unknown> = {
      type: 'object',
      properties: {zip: {type: 'string'}},
      required: ['zip'],
    };
    let activeSchema = citySchema;

    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Dynamic lookup tool',
        inputSchema: activeSchema,
      }),
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const readsAtRegister = cityPropertiesReads;
    await registry.execute('dynamic_lookup', {city: 'Rome'});
    const readsAfterFirstCompile = cityPropertiesReads;
    await registry.execute('dynamic_lookup', {zip: '00100'});

    activeSchema = zipSchema;
    await registry.execute('dynamic_lookup', {zip: '00100'});
    await registry.execute('dynamic_lookup', {city: 'Rome'});

    activeSchema = citySchema;
    await registry.execute('dynamic_lookup', {city: 'Milan'});

    expect({
      readsAtRegister,
      compiledOnceOnFirstCall: readsAfterFirstCompile > 0,
      recompiledLater: cityPropertiesReads !== readsAfterFirstCompile,
      executorCalls,
    }).toEqual({
      readsAtRegister: 0,
      compiledOnceOnFirstCall: true,
      recompiledLater: false,
      executorCalls: 3,
    });
  });
});

